private int getMaxAPIAvailable(String dir) {
  File d = new File(dir);
  if (!d.exists()) throw new RuntimeException("The Android platform directory you have specified (" + dir + ") does not exist. Please check.");
  int maxApi = -1;
  try {
    File[] files = d.listFiles();
    if (files == null) throw new NullPointerException("The directory does not denote a directory or an I/O error occurred.");
    for (File f : files) {
      String name = f.getName();
      if (f.isDirectory() && name.startsWith("android-")) {
        try {
          int v = Integer.decode(name.split("android-")[1]);
          if (v > maxApi) maxApi = v;
        } catch (NumberFormatException e) {
          // Handle malformed directory name
        }
      }
    }
  } catch (SecurityException e) {
    // Handle security exception
  }
  return maxApi;
}
